styles.css:
/* =========================================================
   WORLD OF DREAMS — IDENTIDADE VISUAL & ESTILOS GLOBAIS
   ========================================================= */

/* 1. Seleção de Texto e Barras de Deslocamento */
::selection {
    background-color: #fcd34d !important;
    color: #000000 !important;
}

* {
    scrollbar-width: thin;
    scrollbar-color: #27272a transparent;
}
::-webkit-scrollbar {
    width: 6px;
    height: 6px;
}
::-webkit-scrollbar-track {
    background: transparent;
}
::-webkit-scrollbar-thumb {
    background: #27272a;
    border-radius: 9999px;
}

/* 2. Cabeçalho e Navegação */
header, 
.wp-block-template-part header {
    background: rgba(9, 9, 11, 0.85) !important;
    -webkit-backdrop-filter: blur(20px) !important;
    backdrop-filter: blur(20px) !important;
    border-bottom: 1px solid rgba(39, 39, 42, 0.8) !important;
}

.wp-block-navigation-item__content,
.wp-block-site-title a,
header a {
    color: #f1f5f9 !important;
    font-weight: 700 !important;
    letter-spacing: 0.08em !important;
    text-transform: uppercase !important;
    transition: color 0.25s ease !important;
}

.wp-block-navigation-item__content:hover,
header a:hover {
    color: #fcd34d !important;
}

/* 3. Cartões de Produtos */
.woocommerce ul.products li.product,
.wc-block-grid__product,
.wp-block-woocommerce-all-products .wc-block-grid__product {
    background: linear-gradient(180deg, rgba(14, 18, 30, 0.88) 0%, rgba(8, 10, 18, 0.94) 100%) !important;
    -webkit-backdrop-filter: blur(20px) !important;
    backdrop-filter: blur(20px) !important;
    border: 1px solid rgba(255, 255, 255, 0.12) !important;
    border-top: 1px solid rgba(255, 255, 255, 0.35) !important;
    border-radius: 1.25rem !important;
    padding: 1rem !important;
    box-shadow: 0 16px 40px rgba(0, 0, 0, 0.75) !important;
    transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.35s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.35s ease !important;
}

.woocommerce ul.products li.product:hover,
.wc-block-grid__product:hover {
    transform: translateY(-4px) !important;
    border-color: rgba(252, 211, 77, 0.6) !important;
    box-shadow: 0 20px 45px rgba(0, 0, 0, 0.9) !important;
}

.woocommerce ul.products li.product img,
.wc-block-grid__product-image img {
    border-radius: 0.85rem !important;
    background-color: #0c0e14 !important;
}

/* 4. Tipografia dos Produtos & Preços */
.woocommerce ul.products li.product .woocommerce-loop-product__title,
.wc-block-grid__product-title {
    color: #ffffff !important;
    font-weight: 800 !important;
    text-transform: uppercase !important;
    letter-spacing: 0.03em !important;
    margin-top: 0.75rem !important;
}

.woocommerce ul.products li.product .price,
.wc-block-grid__product-price,
.woocommerce div.product p.price {
    color: #fcd34d !important;
    font-weight: 800 !important;
    font-size: 1.15rem !important;
}

.woocommerce div.product .product_title {
    color: #ffffff !important;
    font-weight: 900 !important;
    letter-spacing: -0.02em !important;
}

/* 5. Botões de Compra e Ação */
.woocommerce a.button,
.woocommerce button.button,
.woocommerce input.button,
.woocommerce #respond input#submit,
.woocommerce a.button.alt,
.woocommerce button.button.alt,
.wp-block-button__link {
    background-color: #fcd34d !important;
    color: #09090b !important;
    font-weight: 900 !important;
    text-transform: uppercase !important;
    letter-spacing: 0.1em !important;
    border-radius: 0.75rem !important;
    border: none !important;
    padding: 0.85rem 1.6rem !important;
    transition: all 0.25s ease !important;
    box-shadow: 0 4px 14px rgba(252, 211, 77, 0.25) !important;
}

.woocommerce a.button:hover,
.woocommerce button.button:hover,
.woocommerce input.button:hover,
.woocommerce #respond input#submit:hover,
.woocommerce a.button.alt:hover,
.woocommerce button.button.alt:hover,
.wp-block-button__link:hover {
    background-color: #fde047 !important;
    color: #000000 !important;
    transform: scale(1.02) !important;
    box-shadow: 0 6px 20px rgba(252, 211, 77, 0.4) !important;
}

/* 6. Formulários e Inputs */
.woocommerce select,
.woocommerce input[type="text"],
.woocommerce input[type="email"],
.woocommerce input[type="tel"],
.woocommerce textarea,
.woocommerce .quantity input.qty {
    background-color: #121216 !important;
    color: #f1f5f9 !important;
    border: 1.5px solid #27272a !important;
    border-radius: 0.65rem !important;
    padding: 0.6rem 0.85rem !important;
}

.woocommerce select:focus,
.woocommerce input:focus,
.woocommerce textarea:focus {
    border-color: #fcd34d !important;
    outline: none !important;
    box-shadow: 0 0 10px rgba(252, 211, 77, 0.25) !important;
}

/* 7. Proteção contra arrasto de imagens */
.woocommerce ul.products li.product img,
.woocommerce-product-gallery img {
    -webkit-user-drag: none !important;
    user-select: none !important;
}

/* 8. Alinhamento Uniforme dos Cartões Iniciais */
@media (min-width: 782px) {
    .wp-block-columns:has(.wod-card-dreams) {
        align-items: stretch !important;
    }

    .wod-card-dreams,
    .wod-card-jonny {
        display: flex !important;
        flex-direction: column !important;
        height: 100% !important;
        justify-content: flex-start !important;
    }

    .wod-card-dreams .wp-block-image,
    .wod-card-jonny .wp-block-image {
        min-height: 155px !important;
        display: flex !important;
        align-items: center !important;
        justify-content: center !important;
        margin-bottom: 1.25rem !important;
    }

    .wod-card-dreams .wp-block-buttons,
    .wod-card-jonny .wp-block-buttons {
        margin-top: auto !important;
        padding-top: 1.5rem !important;
    }
}

.wod-card-dreams:hover {
    border-color: rgba(252, 211, 77, 0.7) !important;
    box-shadow: 0 30px 60px rgba(0, 0, 0, 0.9), 0 0 25px rgba(252, 211, 77, 0.2) !important;
    transform: translateY(-6px) !important;
}

.wod-card-jonny:hover {
    border-color: rgba(192, 132, 252, 0.7) !important;
    box-shadow: 0 30px 60px rgba(0, 0, 0, 0.9), 0 0 25px rgba(192, 132, 252, 0.2) !important;
    transform: translateY(-6px) !important;
}

/* 9. Menu Mobile & Sobreposição (Hambúrguer, Topo & Cores) */
.wp-block-navigation__responsive-container-open {
    background: transparent !important;
    color: #ffffff !important;
    border: none !important;
    box-shadow: none !important;
    padding: 0.5rem !important;
}

.wp-block-navigation__responsive-container-open svg {
    fill: #ffffff !important;
    width: 24px !important;
    height: 24px !important;
}

.wp-block-navigation__responsive-container.is-menu-open {
    position: fixed !important;
    top: 0 !important;
    left: 0 !important;
    width: 100vw !important;
    height: 100vh !important;
    background-color: rgba(7, 9, 15, 0.98) !important;
    z-index: 999999 !important;
    display: flex !important;
    flex-direction: column !important;
    justify-content: flex-start !important;
    align-items: flex-start !important;
    padding: 2.5rem 2rem !important;
    overflow-y: auto !important;
}

.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation__responsive-container-content {
    display: flex !important;
    flex-direction: column !important;
    justify-content: flex-start !important;
    align-items: flex-start !important;
    width: 100% !important;
    min-height: auto !important;
    margin: 0 !important;
    padding: 0 !important;
}

.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation__container {
    display: flex !important;
    flex-direction: column !important;
    align-items: flex-start !important;
    justify-content: flex-start !important;
    gap: 1.25rem !important;
    margin-top: 2.5rem !important;
    margin-bottom: 0 !important;
    padding: 0 !important;
    width: 100% !important;
}

.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation-item,
.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation-item a,
.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation-item__content {
    color: #ffffff !important;
    opacity: 1 !important;
    font-size: 1.25rem !important;
    font-weight: 700 !important;
    letter-spacing: 0.08em !important;
    text-transform: uppercase !important;
    text-decoration: none !important;
    display: inline-block !important;
    padding: 0.4rem 0 !important;
    transition: color 0.2s ease !important;
}

.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation-item a:hover,
.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation-item__content:hover {
    color: #fcd34d !important;
}

.wp-block-navigation__responsive-container-close {
    position: absolute !important;
    top: 1.5rem !important;
    right: 1.5rem !important;
    cursor: pointer !important;
    background: transparent !important;
    border: none !important;
}

.wp-block-navigation__responsive-container-close svg {
    fill: #ffffff !important;
    width: 24px !important;
    height: 24px !important;
    opacity: 1 !important;
}

/* =========================================================
   10. MONTRAS E CARROSSÉIS DE PRODUTOS (ESTILO WORLDOFDREAMS.PT)
   ========================================================= */
.wod-showcase-container {
    max-width: 1280px;
    margin: 2rem auto;
    padding: 0 1.25rem;
}

.wod-showcase-box {
    background: rgba(10, 12, 18, 0.85);
    border-radius: 1.5rem;
    padding: 1.75rem 1.5rem;
    margin-bottom: 2.5rem;
    position: relative;
    backdrop-filter: blur(16px);
}

.wod-box-red {
    border: 1px solid rgba(239, 68, 68, 0.4);
    box-shadow: 0 0 25px rgba(239, 68, 68, 0.12);
}

.wod-box-cyan {
    border: 1px solid rgba(192, 132, 252, 0.4);
    box-shadow: 0 0 25px rgba(192, 132, 252, 0.12);
}

.wod-box-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1.5rem;
}

.wod-box-tag {
    font-size: 0.75rem;
    font-weight: 800;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    margin-bottom: 0.25rem;
}

.wod-box-red .wod-box-tag { color: #f87171; }
.wod-box-cyan .wod-box-tag { color: #c084fc; }

.wod-box-title {
    color: #ffffff;
    font-size: 1.25rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    margin: 0;
}

.wod-nav-arrows {
    display: flex;
    gap: 0.5rem;
}

.wod-arrow-btn {
    background: rgba(255, 255, 255, 0.08);
    border: 1px solid rgba(255, 255, 255, 0.15);
    color: #ffffff;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.2s ease;
}

.wod-arrow-btn:hover {
    background: rgba(252, 211, 77, 0.3);
    border-color: #fcd34d;
    color: #fcd34d;
}

.wod-carousel-track {
    display: flex;
    gap: 1.25rem;
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    scroll-behavior: smooth;
    padding-bottom: 0.75rem;
    scrollbar-width: none;
}
.wod-carousel-track::-webkit-scrollbar { display: none; }

.wod-product-card {
    flex: 0 0 280px;
    scroll-snap-align: start;
    background: rgba(15, 18, 28, 0.95);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 1.25rem;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    transition: transform 0.25s ease, border-color 0.25s ease;
}

.wod-product-card:hover {
    transform: translateY(-4px);
    border-color: rgba(252, 211, 77, 0.5);
}

.wod-card-img-wrap {
    position: relative;
    border-radius: 0.85rem;
    overflow: hidden;
    background: #090b10;
    margin-bottom: 1rem;
    aspect-ratio: 1/1;
}

.wod-card-img-wrap img {
    width: 100%;
    height: 100%;
    object-fit: contain;
}

.wod-badge-360 {
    position: absolute;
    top: 8px;
    left: 8px;
    background: rgba(0, 0, 0, 0.7);
    color: #ffffff;
    font-size: 0.65rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 4px;
    border: 1px solid rgba(255, 255, 255, 0.2);
}

.wod-card-title {
    color: #ffffff;
    font-size: 0.95rem;
    font-weight: 800;
    margin-bottom: 0.4rem;
    line-height: 1.25;
}

.wod-card-desc {
    color: #94a3b8;
    font-size: 0.8rem;
    margin-bottom: 1rem;
    line-height: 1.35;
    flex-grow: 1;
}

.wod-card-btn {
    display: inline-block;
    text-align: center;
    color: #fcd34d;
    font-size: 0.8rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    text-decoration: none;
    padding: 0.5rem 0;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    transition: color 0.2s ease;
}

.wod-card-btn:hover {
    color: #ffffff;
}

/* =========================================================
   11. CORREÇÃO DA CRUZ DE FECHAR MENU (BRANCA E VISÍVEL)
   ========================================================= */
.wp-block-navigation__responsive-container-close,
.has-modal-open .wp-block-navigation__responsive-container-close {
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    visibility: visible !important;
    opacity: 1 !important;
    position: absolute !important;
    top: 1.5rem !important;
    right: 1.5rem !important;
    width: 44px !important;
    height: 44px !important;
    background: rgba(255, 255, 255, 0.12) !important;
    border: 1px solid rgba(255, 255, 255, 0.25) !important;
    border-radius: 50% !important;
    cursor: pointer !important;
    z-index: 10000000 !important;
}

.wp-block-navigation__responsive-container-close svg,
.has-modal-open .wp-block-navigation__responsive-container-close svg {
    display: block !important;
    visibility: visible !important;
    opacity: 1 !important;
    width: 22px !important;
    height: 22px !important;
    fill: #ffffff !important;
    stroke: #ffffff !important;
    color: #ffffff !important;
}

/* =========================================================
   12. PÁGINAS DE FLUXO WOD (SINGLE PRODUCT, CARRINHO, CHECKOUT, PÁGINAS)
   ========================================================= */
.wod-single-product-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 1.5rem 1.25rem;
}

.wod-single-product-panel {
    background: rgba(10, 14, 26, 0.88);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 24px;
    padding: 1.5rem;
    margin: 2.5rem auto;
}

.wod-flow-panel {
    max-width: 1100px;
    margin: 2rem auto;
    padding: 1.5rem;
    background: rgba(10, 14, 26, 0.9);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 20px;
}

.wod-404-container {
    max-width: 720px;
    margin: 0 auto;
    padding: 4rem 1.5rem;
}

/* WooCommerce Blocks — eliminar fundos brancos nativos */
.wc-block-components-sidebar,
.wc-block-checkout__main,
.wc-block-cart__main,
.wc-block-cart__sidebar {
    background: transparent !important;
    color: #f1f5f9 !important;
}

.wc-block-components-sidebar,
.wc-block-checkout__sidebar,
.wc-block-components-totals-wrapper,
.wc-block-components-order-summary,
.wc-block-components-summary,
.wc-block-components-panel,
.wc-block-components-totals-coupon,
.wc-block-components-order-summary-item,
.wc-block-components-totals-item {
    background: #121216 !important;
    border-color: #27272a !important;
    color: #ffffff !important;
}

.wc-block-components-summary-item__label,
.wc-block-components-summary-item__value,
.wc-block-components-totals-item__label,
.wc-block-components-totals-item__value,
.wc-block-components-order-summary-item__description {
    color: #f1f5f9 !important;
}

/* Métodos de pagamento (MB WAY, Cartão Ifthenpay, etc.) */
.wc-block-components-radio-control__option,
.wc-block-components-radio-control-accordion,
.wc-block-components-radio-control-accordion-content {
    background: #121216 !important;
    border-color: #27272a !important;
    color: #ffffff !important;
}

.wc-block-components-radio-control__label,
.wc-block-components-radio-control-accordion__title,
.wc-block-components-payment-method-label {
    color: #ffffff !important;
}

.wc-block-components-text-input input,
.wc-block-components-text-input,
.wc-block-components-combobox .wc-block-components-combobox-control input,
.wc-block-components-select .wc-block-components-select-control,
.wc-block-components-form .wc-block-components-text-input {
    background: #121216 !important;
    color: #ffffff !important;
    border-color: #27272a !important;
}

/* Imagem do produto single: cantos arredondados */
.wp-block-woocommerce-product-image-gallery img,
.woocommerce-product-gallery__image img {
    border-radius: 16px !important;
}

@media (min-width: 782px) {
    .wod-single-product-container {
        padding: 2.5rem 1.5rem;
    }

    .wod-single-product-panel {
        padding: 2.5rem;
    }

    .wod-flow-panel {
        padding: 2rem;
    }
}

/* =========================================================
   13. CARROSSÉIS NATIVOS (PRODUCT QUERY) + SETAS
   ========================================================= */
.wod-carousel-track {
    display: block !important;
    overflow-x: auto !important;
    scroll-snap-type: x mandatory !important;
    scroll-behavior: smooth !important;
    padding-bottom: 0.75rem !important;
    scrollbar-width: none !important;
}

.wod-carousel-track::-webkit-scrollbar { display: none; }

.wod-carousel-track .wp-block-post-template {
    display: flex !important;
    flex-wrap: nowrap !important;
    gap: 1.25rem !important;
    width: max-content !important;
    margin: 0 !important;
    list-style: none !important;
}

.wod-carousel-track .wp-block-post-template > * {
    flex: 0 0 280px !important;
    scroll-snap-align: start !important;
    width: 280px !important;
}

.wod-carousel-track .wod-product-card {
    height: 100%;
    width: 100%;
}

.wod-carousel-track .wc-block-components-product-image {
    border-radius: 0.85rem;
    overflow: hidden;
    background: #090b10;
    margin-bottom: 1rem;
    aspect-ratio: 1/1;
}

.wod-carousel-track .wod-product-card .wc-block-components-product-image img {
    width: 100%;
    height: 100%;
    object-fit: contain;
}

.wod-card-price,
.wod-product-card .wc-block-components-product-price {
    color: #fcd34d !important;
    font-weight: 800 !important;
    font-size: 1.15rem !important;
}

/* Setas nativas (wp:button) como círculos */
.wod-nav-arrows {
    gap: 0.5rem !important;
}

.wod-nav-arrows .wod-arrow-btn .wp-block-button__link {
    width: 36px !important;
    height: 36px !important;
    padding: 0 !important;
    border-radius: 50% !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    background: rgba(255, 255, 255, 0.08) !important;
    border: 1px solid rgba(255, 255, 255, 0.15) !important;
    color: #ffffff !important;
    font-weight: 700 !important;
    font-size: 1rem !important;
    text-decoration: none !important;
}

.wod-nav-arrows .wod-arrow-btn .wp-block-button__link:hover {
    background: rgba(252, 211, 77, 0.3) !important;
    border-color: #fcd34d !important;
    color: #fcd34d !important;
}

/* =========================================================
   14. BRANDING DAS CAIXAS + CARTÕES DE PRODUTO (IMAGENS & TIPOGRAFIA)
   ========================================================= */
/* CAIXA ROXA / LILÁS JONNY D */
.wod-box-purple {
    border-color: rgba(186, 85, 211, 0.4) !important;
    box-shadow: 0 0 25px rgba(186, 85, 211, 0.15) !important;
}
.wod-box-purple .wod-box-tag {
    color: #ba55d3 !important;
}
.wod-box-red .wod-box-tag {
    color: #ff3344 !important;
}

/* IMAGENS DE PRODUTO INTEIRAS E SEM CORTES */
.wod-product-card .wc-block-components-product-image,
.wod-product-card .wp-block-woocommerce-product-image {
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    width: 100% !important;
    height: 220px !important;
    margin-bottom: 12px !important;
    background: transparent !important;
}
.wod-product-card .wc-block-components-product-image img,
.wod-product-card .wp-block-woocommerce-product-image img {
    width: 100% !important;
    height: 100% !important;
    max-height: 220px !important;
    object-fit: contain !important;
}

/* TIPOGRAFIA EQUILIBRADA (Sem textos gigantes) */
.wod-product-card .wp-block-post-title,
.wod-product-card .wp-block-post-title a {
    font-size: 0.95rem !important;
    line-height: 1.25 !important;
    font-weight: 600 !important;
    color: #ffffff !important;
    text-decoration: none !important;
    margin: 6px 0 !important;
    display: -webkit-box !important;
    -webkit-line-clamp: 2 !important;
    -webkit-box-orient: vertical !important;
    overflow: hidden !important;
    min-height: 2.5em !important;
}

.wod-product-card .wp-block-post-excerpt,
.wod-product-card .wp-block-post-excerpt p {
    font-size: 0.8rem !important;
    line-height: 1.3 !important;
    color: rgba(255, 255, 255, 0.65) !important;
    margin: 0 0 10px 0 !important;
    display: -webkit-box !important;
    -webkit-line-clamp: 2 !important;
    -webkit-box-orient: vertical !important;
    overflow: hidden !important;
}

.wod-product-card .wc-block-components-product-price,
.wod-product-card .wp-block-woocommerce-product-price {
    font-size: 1.05rem !important;
    font-weight: 700 !important;
    color: #d4af37 !important;
    margin-bottom: 14px !important;
}

/* =========================================================
   15. PAINEL DO CARRINHO (GLASSMORPHISM ESCURO)
   ========================================================= */
/* PAINEL DO CARRINHO (Glassmorphism Escuro) */
